const fs = require('fs');
const path = require('path');
let inp = {};
try { inp = $('Webhook Trigger').first().json.body || {}; } catch (e) { inp = {}; }
const jobId = (inp.jobId || '').toString().trim();
const product = (inp.product || inp.name || '未命名产品').toString().trim() || '未命名产品';
const ptype = (inp.productType || 'tool').toString().toLowerCase();
const market = (inp.market || 'us').toString().toLowerCase();
const siteUrl = (inp.siteUrl || inp.url || '').toString().trim().replace(/\/+$/,'') || 'https://example.com';
let kws = inp.targetKeywords || inp.keywords || [];
if (typeof kws === 'string') kws = kws.split(/[,、\n;；]+/);
kws = (Array.isArray(kws)?kws:[]).map(x=>String(x).trim()).filter(Boolean);
let langs = inp.languages || [];
if (typeof langs === 'string') langs = langs.split(/[,\s]+/);
langs = (Array.isArray(langs)?langs:[]).map(x=>String(x).trim().replace(/_/g,'-')).filter(Boolean);
const htmlSample = (inp.htmlSample || inp.html || '').toString();
function slugify(t){ return (t||'').toLowerCase().trim().replace(/['"]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80)||'site'; }
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function strip(s){ return String(s||'').replace(/<[^>]+>/g,'').trim(); }
const slug = slugify(product);

// ---- R9/R12 解析 + 逐项判定 ----
function first(re){ const m = htmlSample.match(re); return m ? m[1].trim() : null; }
const title = first(/<title[^>]*>([\s\S]*?)<\/title>/i);
const desc = first(/<meta[^>]+name=["']description["'][^>]+content=["']([\s\S]*?)["']/i) || first(/<meta[^>]+content=["']([\s\S]*?)["'][^>]+name=["']description["']/i);
const canonical = first(/<link[^>]+rel=["']canonical["'][^>]+href=["']([\s\S]*?)["']/i) || first(/<link[^>]+href=["']([\s\S]*?)["'][^>]+rel=["']canonical["']/i);
const h1s = (htmlSample.match(/<h1[^>]*>[\s\S]*?<\/h1>/gi)||[]).map(strip);
const h2s = (htmlSample.match(/<h2[^>]*>[\s\S]*?<\/h2>/gi)||[]).map(strip);
const h3s = (htmlSample.match(/<h3[^>]*>[\s\S]*?<\/h3>/gi)||[]).map(strip);
const imgTags = htmlSample.match(/<img[^>]*>/gi)||[];
const imgsTotal = imgTags.length;
const imgsAlt = imgTags.filter(t=>{ const m=t.match(/alt=["']([\s\S]*?)["']/i); return m && m[1].trim(); }).length;
const hrefs = (htmlSample.match(/<a[^>]+href=["']([\s\S]*?)["']/gi)||[]).map(t=>{const m=t.match(/href=["']([\s\S]*?)["']/i);return m?m[1]:'';});
const internalLinks = hrefs.filter(h=>h && !/^(https?:\/\/|mailto:|tel:|javascript:|#)/i.test(h)).length;
const lower = htmlSample.toLowerCase();
const hasSample = htmlSample.trim().length > 0;

const ITEMS_DEF = [
  ['title','Title 标题','搜索结果首屏展示，决定点击率','50-60 字符，含 1 个核心词 + 品牌，靠前放置','<title>核心关键词 - 产品卖点 | 品牌名</title>'],
  ['description','Meta Description','搜索摘要，影响点击率','120-158 字符，含关键词 + 行动号召（CTA）','<meta name="description" content="用一句话说清价值 + 关键词 + CTA，控制在 158 字符内。">'],
  ['canonical','Canonical 规范链接','避免重复内容分散权重','每页唯一自引用 canonical，带绝对 URL','<link rel="canonical" href="https://example.com/page">'],
  ['h1','H1 主标题','每页唯一，点明主题','每页有且仅有一个 H1，含核心关键词','<h1>页面核心关键词 + 用户价值</h1>'],
  ['h2h3','H2/H3 层级','结构化正文，利于理解与富摘要','H2 分段、H3 细分，层级不跳级','<h2>分段标题</h2>\\n<h3>子标题</h3>'],
  ['alt','图片 Alt','无障碍 + 图片搜索入口','每张内容图都有描述性 alt（装饰图 alt=""）','<img src="..." alt="描述图片内容并含相关词">'],
  ['internal','内链密度','分发权重、延长停留','每页 3-5 条相关内链，锚文本含目标词','<a href="/related-page">含目标词的锚文本</a>'],
  ['viewport','移动端 viewport','移动优先索引必备','必须声明 viewport，移动友好','<meta name="viewport" content="width=device-width, initial-scale=1">'],
  ['og','Open Graph 社交卡片','社交分享点击率','og:title / og:description / og:image 三件套','<meta property="og:title" content="分享标题">\\n<meta property="og:image" content="https://.../cover.png">'],
];
const kw = kws[0] || '';
function statusOf(id){
  if(!hasSample) return {status:'check', found:''};
  if(id==='title'){ const tl=(title||'').length; const hasKw = kw ? (title||'').toLowerCase().includes(kw.toLowerCase()) : true;
    return {status: !title ? 'fail' : (tl<30||tl>70||!hasKw)?'partial':'pass', found:'长度 '+tl+' 字符；'+(hasKw?'含':'未含')+'目标词「'+kw+'」'}; }
  if(id==='description'){ const dl=(desc||'').length;
    return {status: !desc?'fail':(dl<70||dl>170)?'partial':'pass', found:'长度 '+dl+' 字符'}; }
  if(id==='canonical'){ return {status: canonical?'pass':'fail', found: canonical?('已声明：'+canonical.slice(0,60)):'未找到 canonical'}; }
  if(id==='h1'){ const n=h1s.length; return {status:n===1?'pass':(n===0?'fail':'partial'), found:'H1 数量 '+n+(n?('（'+h1s.slice(0,2).join(' | ')+'）'):'')}; }
  if(id==='h2h3'){ return {status:(h2s.length>=2&&h3s.length>=1)?'pass':((h2s.length+h3s.length)>0?'partial':'fail'), found:'H2 ×'+h2s.length+' / H3 ×'+h3s.length}; }
  if(id==='alt'){ if(imgsTotal===0) return {status:'check',found:'页面无图片（跳过）'};
    return {status: imgsAlt===imgsTotal?'pass':(imgsAlt===0?'fail':'partial'), found:imgsAlt+'/'+imgsTotal+' 图片有 alt'}; }
  if(id==='internal'){ return {status:internalLinks>=3?'pass':(internalLinks>=1?'partial':'fail'), found:'内链约 '+internalLinks+' 条'}; }
  if(id==='viewport'){ return {status: lower.includes('viewport')?'pass':'fail', found: lower.includes('viewport')?'已声明':'未声明'}; }
  if(id==='og'){ return {status: (lower.includes('property="og:')||lower.includes("property='og:"))?'pass':'partial', found:(lower.includes('property="og:')||lower.includes("property='og:"))?'含 OG 标签':'缺 OG 标签'}; }
  return {status:'check', found:''};
}
const items = ITEMS_DEF.map(d=>{ const s=statusOf(d[0]); return {id:d[0],name:d[1],desc:d[2],ideal:d[3],fix:d[4],status:s.status,found:s.found}; });
const scored = items.filter(i=>['pass','partial','fail'].includes(i.status));
const score = scored.length ? Math.round(scored.reduce((a,i)=>a+(i.status==='pass'?1:i.status==='partial'?0.5:0),0)/scored.length*100) : null;

// ---- R8 hreflang ----
if(!langs.length) langs=['en'];
const seen=new Set(); const ulangs=[]; for(const l of langs){ if(!seen.has(l.toLowerCase())){seen.add(l.toLowerCase()); ulangs.push(l);} }
langs = ulangs;
const entries = langs.map(l=>{ const short=l.split('-')[0]; return {lang:l, short:short, url:siteUrl+'/'+short+'/', hreflang: l.includes('-')?l:short}; });
const snippetLines = entries.map(e=>'<link rel="alternate" hreflang="'+e.hreflang+'" href="'+e.url+'" />');
snippetLines.push('<link rel="alternate" hreflang="x-default" href="'+siteUrl+'/" />');
const snippet = snippetLines.join('\n');
const rules = [
  '每个语言页都要写「全量」hreflang 标签（含自引用），不能只写别的语言。',
  '双向互指：A 页声明 B，B 页也必须声明 A，否则 Google 视为无效信号。',
  'hreflang 指向的 URL 必须可索引、且与该语言内容一致（语言/地区码用 en / en-US / zh-CN）。',
  'x-default 兜底：语言选择器页或默认语言页用 hreflang="x-default"。',
  'hreflang 与 canonical 组合：canonical 指向本语言页自身，hreflang 指向各语言版本，两者不冲突。',
  '防重复内容：不同语言必须是「独立 URL + 独立内容」，不要同 URL 仅换语言包。',
];
const hreflang = {languages:langs, strategy:{recommended:'子路径（subpath）', why:'子路径 /en/ /zh/ 共享域名权重、部署简单、hreflang 最不易出错；子域名分散权重，ccTLD 成本高。', pattern:siteUrl+'/{lang}/'}, entries:entries, snippet:snippet, rules:rules};

// ---- R9 head scaffold ----
const kw0 = kws[0] || product;
const tTitle = kw0+' - '+product;
const tDesc = product+'：'+kw0+'，上手即用，帮你高效进阶。立即免费试用。';
const headScaffold = ['<head>',
  '  <title>'+tTitle+'</title>',
  '  <meta name="description" content="'+tDesc+'">',
  '  <link rel="canonical" href="'+siteUrl+'/">',
  '  <meta name="viewport" content="width=device-width, initial-scale=1">',
  '  <meta property="og:title" content="'+tTitle+'">',
  '  <meta property="og:description" content="'+tDesc+'">',
  '  <meta property="og:image" content="'+siteUrl+'/og-cover.png">',
  '  <meta property="og:url" content="'+siteUrl+'/">',
  '  <meta property="og:type" content="website">',
  '  <!-- R8 多语言 hreflang（每页全量声明，含自引用） -->',
  ...snippetLines.map(l=>'  '+l),
  '</head>'].join('\n');

// ---- R14 ASO（APP）----
function clip(s,n){ s=String(s||'').trim(); return s.length<=n?s:s.slice(0,n-1)+'…'; }
const isApp = ['mobile-app','app','mobile'].includes(ptype);
let aso = null;
if(isApp){
  const core = (kws[0]||product).trim();
  const iosTitle = clip(product+' - '+core+' 练习助手', 30);
  const iosSubtitle = clip('轻松学会，每天进步一点点', 30);
  const titleWords = new Set(iosTitle.toLowerCase().match(/[\w\u4e00-\u9fff]+/g)||[]);
  const kwTokens = [];
  for(const k of kws){ for(const tok of (k.toLowerCase().match(/[\w\u4e00-\u9fff]+/g)||[])){ if(tok.length>1 && !titleWords.has(tok) && !kwTokens.includes(tok)) kwTokens.push(tok); } }
  for(const extra of ['practice','trainer','learn','lessons','free']){ if(!kwTokens.includes(extra) && !titleWords.has(extra)) kwTokens.push(extra); }
  const iosKeyword = clip(kwTokens.join(','), 100);
  const screenshots = [
    {n:1,caption:'首屏：一句话讲清核心价值（对应副标题）',why:'决定下载的第一眼'},
    {n:2,caption:'核心功能演示：'+core,why:'证明「能解决我的问题」'},
    {n:3,caption:'进阶/段位/成就体系（差异化）',why:'给持续使用理由'},
    {n:4,caption:'真实数据或用户好评截图',why:'社会证明，降低疑虑'},
    {n:5,caption:'多端/离线/跨设备（如适用）',why:'补足使用场景'},
    {n:6,caption:'限时优惠 / 免费试用号召',why:'临门一脚促转化'},
  ];
  const primary = market==='cn' ? 'zh-CN' : 'en-US';
  const allLocs = [primary, ...langs.filter(l=>l!==primary)];
  const seenL=new Set(); const locales=[];
  for(const loc of allLocs){ if(seenL.has(loc)) continue; seenL.add(loc);
    const isCn = loc.toLowerCase().startsWith('zh');
    locales.push({locale:loc, title:clip(product+' - '+core+(isCn?'练习助手':' Practice'),30),
      subtitle:clip(isCn?'每天 10 分钟，稳步进阶':'10 min a day, steady progress',30),
      keywordField:clip(isCn?'练习,训练,学习,入门,进阶':'practice,training,learn,beginner,pro',100),
      desc: product+' 是一款专注「'+core+'」的'+(isCn?'练习工具':'practice tool')+'。'+(isCn?'上手即用，段位体系让你看清进步。':'Get started instantly and see your progress.')});
  }
  aso = {isApp:true,
    ios:{title:iosTitle,titleChars:iosTitle.length,subtitle:iosSubtitle,subtitleChars:iosSubtitle.length,
      keywordField:iosKeyword,keywordChars:iosKeyword.length,
      keywordTips:['100 字符上限：用逗号分隔单词/短语，别写完整句子，别加空格（省字符）。','标题已含的词不必在关键词字段重复（标题权重更高）。','覆盖长尾与竞品词（不侵权），按市场本地化。']},
    screenshots:screenshots, locales:locales,
    android:{shortDesc:clip(product+'：'+core+'练习助手，每天 10 分钟进步',80),
      fullDescSkeleton:['【一句话】'+product+' 帮你高效练习 '+core+'。','【痛点】练习没方向、进步看不见、坚持不下去？','【解法】'+product+' 提供结构化练习 + 即时反馈 + 进度可视化。','【特色】① 分级训练 ② 段位/成就体系 ③ 离线可用 ④ 无广告干扰','【行动】立即下载，开始你的第一次练习。']}};
}

const marketLabel = market==='cn' ? '中国大陆' : (market==='both' ? '海外 + 中国大陆' : '海外/全球');
const ICON = {pass:'✅',partial:'⚠️',fail:'❌',check:'☑️'};

// ---- 报告 ----
const L = [];
L.push('════════ 技术 SEO / ASO / 多语言优化方案（R9/R12/R14/R8） ════════');
L.push('产品：'+product+'　类型：'+ptype+'　市场：'+marketLabel);
L.push(score==null ? '技术 SEO：未提供 HTML，给出「应达标准 + 修复脚手架」清单' : '技术 SEO 体检分：'+score+'/100　（逐项见下）');
L.push('');
L.push('【一、技术 SEO 检查清单】（R9/R12）');
items.forEach(it=>{
  L.push('  '+(ICON[it.status]||'☑️')+' '+it.name+'：'+it.ideal);
  if(it.found) L.push('        实测：'+it.found);
  L.push('        修复：'+it.fix);
});
L.push('');
L.push('【二、多语言 + hreflang】（R8 防重复内容惩罚）');
L.push('  推荐 URL 结构：'+hreflang.strategy.recommended+' —— '+hreflang.strategy.why);
L.push('  模式：'+hreflang.strategy.pattern);
L.push('  hreflang 标签（写入每一页 <head>，全量含自引用）：');
snippetLines.forEach(l=>L.push('    '+l));
L.push('  规则：');
rules.forEach(r=>L.push(' · '+r));
L.push('');
L.push('【三、技术 SEO 内建 <head> 脚手架】（R9 建站时即正确）');
headScaffold.split('\n').forEach(l=>L.push('    '+l));
if(aso){
  L.push('');
  L.push('【四、ASO 商店页优化】（R14 · APP 专属）');
  L.push('  iOS 标题（'+aso.ios.titleChars+'/30）：'+aso.ios.title);
  L.push('  iOS 副标题（'+aso.ios.subtitleChars+'/30）：'+aso.ios.subtitle);
  L.push('  iOS 关键词字段（'+aso.ios.keywordChars+'/100）：'+aso.ios.keywordField);
  aso.ios.keywordTips.forEach(t=>L.push(' · '+t));
  L.push('  截图卖点清单：');
  aso.screenshots.forEach(s=>L.push('    '+s.n+'. '+s.caption+' —— '+s.why));
  L.push('  本地化商店页：');
  aso.locales.forEach(l=>{ L.push('    ['+l.locale+'] 标题：'+l.title+'｜副标题：'+l.subtitle); L.push('        关键词：'+l.keywordField); });
  L.push('  Android 短描述（80）：'+aso.android.shortDesc);
  L.push('  Android 完整描述骨架：');
  aso.android.fullDescSkeleton.forEach(s=>L.push(' · '+s));
}
L.push('');
L.push('提示：技术 SEO 一次做对成本最低——建站时就套用 <head> 脚手架，比上线后补救省 10 倍力。');
const report = L.join('\n');

// ---- techseo.html ----
const rows = items.map(it=>{
  const icon=ICON[it.status]||'☑️';
  return '<tr><td>'+icon+'</td><td><b>'+esc(it.name)+'</b><div class="sub">'+esc(it.desc)+'</div>'+(it.found?'<div class="found">实测：'+esc(it.found)+'</div>':'')+'</td><td>'+esc(it.ideal)+'</td><td><code>'+esc(it.fix)+'</code></td></tr>';
}).join('');
const hlLines = snippetLines.map(l=>'<div class="code">'+esc(l)+'</div>').join('');
const ruleItems = rules.map(r=>'<li>'+esc(r)+'</li>').join('');
const headLines = headScaffold.split('\n').map(l=>'<div class="code">'+esc(l)+'</div>').join('');
let asoHtml = '';
if(aso){
  const locRows = aso.locales.map(l=>'<tr><td><b>'+esc(l.locale)+'</b></td><td>'+esc(l.title)+'</td><td>'+esc(l.subtitle)+'</td><td><code>'+esc(l.keywordField)+'</code></td></tr>').join('');
  const shotItems = aso.screenshots.map(s=>'<li><b>'+s.n+'.</b> '+esc(s.caption)+' — '+esc(s.why)+'</li>').join('');
  const tips = aso.ios.keywordTips.map(t=>'<li>'+esc(t)+'</li>').join('');
  const andSk = aso.android.fullDescSkeleton.map(s=>'<li>'+esc(s)+'</li>').join('');
  asoHtml = '<h2>四、ASO 商店页优化（APP 专属 · R14）</h2><div class="card"><div class="k">iOS 标题（'+aso.ios.titleChars+'/30）</div><div class="v">'+esc(aso.ios.title)+'</div><div class="k">iOS 副标题（'+aso.ios.subtitleChars+'/30）</div><div class="v">'+esc(aso.ios.subtitle)+'</div><div class="k">iOS 关键词字段（'+aso.ios.keywordChars+'/100）</div><code class="block">'+esc(aso.ios.keywordField)+'</code><ul>'+tips+'</ul><div class="k">截图卖点</div><ul>'+shotItems+'</ul></div><table><thead><tr><th>语言</th><th>标题</th><th>副标题</th><th>关键词</th></tr></thead><tbody>'+locRows+'</tbody></table><div class="card"><div class="k">Android 短描述</div><code class="block">'+esc(aso.android.shortDesc)+'</code><ul>'+andSk+'</ul></div>';
}
const html = '<!DOCTYPE html><html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>技术 SEO / ASO 优化方案 · '+esc(product)+'</title><style>body{font-family:-apple-system,"Segoe UI",Roboto,"Microsoft YaHei",sans-serif;margin:0;background:#0c1220;color:#fffdf9;line-height:1.65;padding:32px 20px 60px}.wrap{max-width:960px;margin:0 auto}h1{font-size:26px;margin:0 0 6px}h2{font-size:18px;margin:32px 0 12px;padding-left:10px;border-left:4px solid #5b34e6}.meta{color:#8b6ef0;font-size:13px;margin-bottom:24px}.card{background:#17131b;border:1px solid #4a25c9;border-radius:12px;padding:14px;margin:10px 0}.card .k{color:#5b34e6;font-size:12px}.card .v{font-size:16px;font-weight:700;margin-top:4px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid #4a25c9;vertical-align:top}th{color:#5b34e6;font-weight:600;font-size:12px}.sub{color:#5b34e6;font-size:11px}.found{color:#8b6ef0;font-size:11.5px;margin-top:3px}code{font-family:ui-monospace,Menlo,Consolas,monospace;background:#17131b;padding:2px 6px;border-radius:6px;font-size:11.5px;color:#8b6ef0;word-break:break-word}code.block{display:block;padding:8px 10px;margin:6px 0;white-space:pre-wrap}.code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12px;color:#8b6ef0;background:#17131b;padding:5px 10px;border-radius:6px;margin:3px 0;word-break:break-word}ul{padding-left:20px}li{margin:6px 0}</style></head><body><div class="wrap"><h1>技术 SEO / ASO / 多语言优化方案</h1><div class="meta">'+esc(product)+' · '+esc(marketLabel)+' · 体检分 '+(score==null?'—':score+'/100')+'</div><h2>一、技术 SEO 检查清单（R9/R12）</h2><table><thead><tr><th></th><th>项目</th><th>理想标准</th><th>修复代码</th></tr></thead><tbody>'+rows+'</tbody></table><h2>二、多语言 + hreflang（R8）</h2><div class="card"><div class="k">URL 结构：'+esc(hreflang.strategy.recommended)+'</div><div>'+esc(hreflang.strategy.why)+'</div><code class="block">'+esc(hreflang.strategy.pattern)+'</code>'+hlLines+'<div class="k">防重复内容规则</div><ul>'+ruleItems+'</ul></div><h2>三、技术 SEO 内建 &lt;head&gt; 脚手架（R9）</h2><div class="card">'+headLines+'</div>'+asoHtml+'</div></body></html>';

// ---- 落盘 ----
let files = [];
try {
  const SITES = '/home/node/sites';
  const outDir = path.join(SITES, '_techseo', slug);
  fs.mkdirSync(outDir, {recursive:true});
